import RNA, random, multiprocessing as mp
target = '.((.((.((..((.(...).)).))..))....)).'
base = 'GCCGCAUACGAGGGGGGUCGCCAGUUUUGCUUAGGG'

def dist(s):
    fc = RNA.fold_compound(s)
    mfe,_ = fc.mfe()
    return sum(1 for a,b in zip(target,mfe) if a!=b)

def worker(seed):
    random.seed(seed)
    cur = base
    cur_d = dist(cur)
    best_d = cur_d
    best = cur
    for _ in range(20000):
        s = list(cur)
        if random.random() < 0.5:
            positions = random.sample(list(range(0,6))+list(range(27,33)), random.randint(1,3))
        else:
            positions = random.sample(range(36), random.randint(1,3))
        for p in positions:
            s[p] = random.choice('ACGU')
        cand = ''.join(s)
        d = dist(cand)
        if d <= cur_d or random.random() < 0.03:
            cur = cand
            cur_d = d
        if d < best_d:
            best_d = d
            best = cand
            if d == 0:
                return (0, cand)
    return (best_d, best)

if __name__ == '__main__':
    with mp.Pool(32) as p:
        results = p.map(worker, range(32))
    results.sort(key=lambda x: x[0])
    for r in results[:5]:
        print(r[0], r[1])
