import RNA, random, multiprocessing as mp
target = '.((.((.((..((.(...).)).))..))....)).'
pairs_1idx = [(2,35),(3,34),(5,29),(6,28),(8,25),(9,24),(12,22),(13,21),(15,19)]

def dist(s):
    fc = RNA.fold_compound(s)
    mfe,_ = fc.mfe()
    return sum(1 for a,b in zip(target,mfe) if a!=b)

def rand_init(seed):
    random.seed(seed)
    seq = ['.']*36
    pair_choices = [('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')]
    for (a,b) in pairs_1idx:
        x,y = random.choice(pair_choices)
        seq[a-1] = x
        seq[b-1] = y
    for i,c in enumerate(target):
        if c=='.':
            seq[i] = random.choice('ACGU')
    return ''.join(seq)

def worker(seed):
    random.seed(seed*7+1)
    cur = rand_init(seed)
    cur_d = dist(cur)
    best_d = cur_d
    best = cur
    for _ in range(30000):
        s = list(cur)
        positions = random.sample(range(36), random.randint(1,4))
        for p in positions:
            s[p] = random.choice('ACGU')
        cand = ''.join(s)
        d = dist(cand)
        if d <= cur_d or random.random() < 0.05:
            cur = cand
            cur_d = d
        if d < best_d:
            best_d = d
            best = cand
            if d == 0:
                return (0, cand)
    return (best_d, best)

if __name__ == '__main__':
    with mp.Pool(32) as p:
        results = p.map(worker, range(64))
    results.sort(key=lambda x: x[0])
    for r in results[:10]:
        print(r[0], r[1])
